rowdata.pyStepsJavaSource:
//Get stream
StringMap keys = new HashStringMap();
keys.putString("pxObjClass", "Rule-Obj-HTML");
keys.putString("pyStreamName",tools.getParamValue("StreamName"));
if (myStepPage == null
    || myStepPage.getClassName().length() == 0) {
  keys.putString("pyClassName", "@baseclass");
}
tools.putParamValue("Markup", tools.getStream(keys, null));
tools.putParamValue("UseCompactStylesforPDF", "false");

String Markup=tools.getParamValue("Markup");
String styles=tools.getParamValue("MarkupStyles");
String stylePlaceHolder = "<!--Styles Removed by ExportToPDF-->";
String pattern ="<link(\\s)rel=\"stylesheet\"(\\s)type=\"text/css\"(\\s)href=\"webwb/(.*?)>";
Markup=Markup.replaceAll(pattern,stylePlaceHolder);
Markup=Markup.replaceFirst(stylePlaceHolder,styles);
tools.putParamValue("Markup",Markup);

HTMLStream = tools.getParamValue("Markup").trim();


if (HTMLStream.length() == 0)
{
  throw new IllegalArgumentException("Parameter page is not set up correctly for HTMLtoPDF. You MUST populate \"Markup\" parameter with HTML content or set \"StreamName\" parameter to the key of a valid, non-empty HTML Record. ");
}

//Get the PDF generation utility class
PDFUtils pdfUtil=tools.getPDFUtils();

//BUG- 32651 Back-Ported HFix-2932
//Get the PDF bytes.
byte[] byteArray = pdfUtil.generatePDF(HTMLStream,tools.getParameterPage());

if (byteArray == null || byteArray.length == 0)
{
    oLog.error("PDFUtils did not return any content for HTMLtoPDF");
}
else
{
    //Put the byte array in a parameter
    tools.putParamValue("PDFDocument",byteArray);
}
